/* ===== /Webフォント ===== */
/* ===== アートメイク除去ページ（女性向け配色：ローズ・モーヴ）（.tt-guide 内だけに適用） ===== */

.tt-guide {
  --bg0: #5F2B43;
  --bg1: #7F395A;
  --bg2: #A44773;
  --tx: #FDB9DB;
  --tx2: #ECCBDB;
  --tx3: #C89DB2;
  /* 斜めカット：全箇所同じ傾き（レーザービームも同じ角度） */
  --cut: 88px;
  --ang: -4.75deg;
  --line: rgba(253, 179, 216, .16);
  --glass: rgba(158, 77, 115, .58);
  --hi: rgba(255, 255, 255, .14);
  --cyan: #FB6DCA;
  --blue: #FA4EA4;
  --g: #2EE89A;
  --r: #FF4D6A;
  --v: #A784FF;
  --jp: "Zen Kaku Gothic New", "Hiragino Kaku Gothic ProN", "Yu Gothic", YuGothic, "Noto Sans JP", sans-serif;
  --en: "Cormorant Garamond", "Shippori Mincho", serif;
  position: relative;
  max-width: 1080px;
  margin: 0 auto;
  padding: 0;
  color: var(--tx);
  font-family: var(--jp);
  font-size: 15px;
  font-weight: 400;
  line-height: 1.95;
  letter-spacing: .04em;
  background:
    radial-gradient(900px 500px at -10% 40%, rgba(167, 132, 255, .12), transparent 60%),
    radial-gradient(900px 600px at 110% 70%, rgba(250, 78, 164, .14), transparent 60%),
    var(--bg0);
  border-radius: 32px;
  overflow: hidden;
  word-break: auto-phrase;
  line-break: strict;
  -webkit-font-smoothing: antialiased;
}
.tt-guide *, .tt-guide *::before, .tt-guide *::after { box-sizing: border-box; }
.tt-guide p, .tt-guide figure, .tt-guide dl, .tt-guide dd, .tt-guide dt { margin: 0; padding: 0; }
.tt-guide ul, .tt-guide ol { margin: 0; padding: 0; list-style: none; }
.tt-guide li { margin: 0; padding: 0; background: none; border: 0; }
.tt-guide li::marker { content: ""; }
.tt-guide img { display: block; max-width: 100%; height: auto; border: 0; box-shadow: none; border-radius: 0; }
.tt-guide a { color: var(--cyan); }
.tt-guide a:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; border-radius: 6px; }
.tt-guide strong { font-weight: 700; color: #fff; }
/* 改行：文節単位（auto-phrase）。text-wrap: pretty は Chromium で文節改行を無効にするため使わない */
.tt-guide .tt-summary dd, .tt-guide .tt-case-detail dd, .tt-guide .tt-tl-state, .tt-guide .tt-tl-care { text-wrap: balance; }

/* ---------- ヒーロー ---------- */
.tt-guide .tt-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.22fr) minmax(0, .78fr);
  gap: 12px;
  align-items: center;
  padding: 76px 56px calc(var(--cut) + 40px);
  isolation: isolate;
  background:
    radial-gradient(700px 520px at 78% 30%, rgba(250, 78, 164, .42), transparent 65%),
    linear-gradient(rgba(253, 158, 206, .055) 1px, transparent 1px) center top / 44px 44px,
    linear-gradient(90deg, rgba(253, 158, 206, .055) 1px, transparent 1px) center top / 44px 44px,
    linear-gradient(180deg, #A34773 0%, var(--bg1) 100%);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - var(--cut)), 0 100%);
}
/* 3本のレーザー（532nm 緑・694nm 赤・1064nm 紫）
   角度・高さ・周期・開始をずらし、毎回違う重なり方で端から端まで流しきる */
.tt-guide .tt-lasers {
  position: absolute; inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}
.tt-guide .tt-laser {
  position: absolute;
  left: -20%;
  width: 140%;
  height: 18px;
  margin-top: -9px;
  overflow: hidden;
  transform: rotate(var(--a));
}
/* 芯（細く明るい光）と、にじむ光の2層。どちらも同じ動きで流れる */
.tt-guide .tt-laser::before,
.tt-guide .tt-laser::after {
  content: "";
  position: absolute; left: 0; width: 100%;
  background: linear-gradient(90deg, transparent 24%, var(--c) 43%, #fff 50%, var(--c) 57%, transparent 76%);
  transform: translateX(-100%);
  animation: tt2-laser var(--d) cubic-bezier(.42, 0, .58, 1) var(--w) infinite;
}
.tt-guide .tt-laser::before { top: 8px; height: var(--h, 1px); }
.tt-guide .tt-laser::after { top: 7px; height: 4px; filter: blur(3px); opacity: .5; }
.tt-guide .tt-laser-532  { --h: 2px; --c: #2EE89A; --a: -9deg;   top: 34%; --d: 7.6s;  --w: .3s; }
.tt-guide .tt-laser-694  { --c: #FF4D6A; --a: -3.5deg; top: 50%; --d: 9.4s;  --w: 2.2s; }
.tt-guide .tt-laser-1064 { --c: #A784FF; --a: 5deg;    top: 66%; --d: 8.3s;  --w: 4.1s; }
/* 1周の前半〜7割でゆっくり横断し、残りは画面外で待つ（周期が違うので毎回重なり方が変わる） */
@keyframes tt2-laser {
  0%   { transform: translateX(-100%); }
  72%  { transform: translateX(100%); }
  100% { transform: translateX(100%); }
}

.tt-guide .tt-place {
  display: inline-block;
  margin-bottom: 22px;
  padding: 5px 14px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, .04);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: .06em;
  color: var(--tx2);
  text-wrap: balance;
}
.tt-guide .tt-title {
  margin: 0 0 26px;
  padding: 0;
  border: 0;
  background: none;
  color: #fff;
  font-family: var(--jp);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: .02em;
}
.tt-guide .tt-title::before, .tt-guide .tt-title::after { display: none; }
.tt-guide .tt-title-main {
  display: block;
  font-size: clamp(30px, 4.6vw, 52px);
  text-wrap: balance;
  background: linear-gradient(100deg, #fff 30%, #FDB9DE 60%, #FDB2DF 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.tt-guide .tt-title-sub {
  display: block;
  margin-top: 16px;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.7;
  letter-spacing: .06em;
  color: var(--tx2);
  text-wrap: balance;
}
.tt-guide .tt-lead { max-width: 34em; margin-bottom: 30px; color: var(--tx2); }
.tt-guide .tt-points { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; margin-bottom: 22px; }
/* 診療日（日曜日限定）のお知らせ */
.tt-guide .tt-day {
  display: block; width: fit-content; max-width: 100%;
  margin-bottom: 26px;
  padding: 10px 18px;
  border: 1px solid rgba(255, 77, 106, .55);
  border-radius: 12px;
  background: rgba(255, 77, 106, .10);
  color: #fff;
  font-size: 14px;
  line-height: 1.6;
  text-wrap: balance;
}
.tt-guide .tt-day strong { color: #FF8597; font-size: 16px; margin: 0 2px; }
.tt-guide .tt-day span { display: block; font-size: 12px; color: #ECCBDB; }
.tt-guide .tt-point {
  position: relative;
  padding: 14px 14px;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(255, 255, 255, .08), rgba(255, 255, 255, .02));
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi), 0 14px 30px -18px rgba(0, 0, 0, .8);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
}
.tt-guide .tt-point strong { display: block; font-size: 13.5px; line-height: 1.5; letter-spacing: .01em; white-space: nowrap; }
.tt-guide .tt-point span { display: block; margin-top: 4px; font-family: var(--en); font-size: 12px; line-height: 1.5; color: var(--tx3); text-wrap: balance; }

.tt-guide .tt-hero-device { position: relative; z-index: 2; margin: 0; text-align: center; }
.tt-guide .tt-device-stage { position: relative; max-width: 300px; margin: 0 auto; padding-bottom: 44px; }
/* スポットライト */
.tt-guide .tt-device-stage::before {
  content: "";
  position: absolute;
  left: 50%; top: -12%;
  width: 190%; height: 125%;
  transform: translateX(-50%);
  background: radial-gradient(closest-side, rgba(252, 128, 194, .38), rgba(250, 78, 164, .12) 55%, transparent 75%);
  z-index: 0;
}
.tt-guide .tt-pedestal {
  position: absolute; left: 50%; bottom: 8px;
  width: 150%; height: 74px;
  transform: translateX(-50%);
  border-radius: 50%;
  background:
    radial-gradient(closest-side, rgba(251, 109, 202, .55), rgba(250, 78, 164, .2) 55%, transparent 80%);
  box-shadow: 0 0 0 1px rgba(251, 109, 202, .25);
  z-index: 0;
}
.tt-guide .tt-device-img {
  position: relative;
  z-index: 1;
  width: 100%;
  filter: drop-shadow(0 30px 28px rgba(0, 0, 0, .65)) drop-shadow(0 0 22px rgba(252, 138, 197, .25));
  animation: tt2-rise 1.2s cubic-bezier(.2, .8, .2, 1) both, tt2-float 6s ease-in-out 1.2s infinite;
}
@keyframes tt2-rise { from { opacity: 0; transform: translateY(46px); } to { opacity: 1; transform: none; } }
@keyframes tt2-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
.tt-guide .tt-device-cap { font-family: var(--en); font-size: 15px; font-weight: 500; letter-spacing: .08em; color: #fff; }
.tt-guide .tt-device-cap span { display: block; font-family: var(--jp); font-size: 12px; color: var(--tx3); letter-spacing: .04em; }

/* ---------- ボタン ---------- */
.tt-guide .tt-cta { text-align: center; }
.tt-guide .tt-cta-left { text-align: left; }
.tt-guide .tt-btn {
  position: relative;
  display: inline-block;
  padding: 18px 42px;
  border-radius: 999px;
  overflow: hidden;
  background: linear-gradient(100deg, #FDB9E3 0%, #FFFFFF 50%, #FDB9DE 100%);
  color: #7F395A;
  font-weight: 700;
  font-size: 15px;
  letter-spacing: .08em;
  text-decoration: none;
  white-space: nowrap;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .6), 0 0 32px rgba(251, 109, 202, .45), 0 18px 36px -12px rgba(0, 0, 0, .7);
  transition: transform .25s, box-shadow .25s;
}
.tt-guide .tt-btn::after {
  content: "";
  position: absolute; top: 0; bottom: 0; left: -40%;
  width: 30%;
  background: linear-gradient(100deg, transparent, rgba(251, 109, 202, .55), transparent);
  transform: skewX(-20deg);
  animation: tt2-shine 4s ease-in-out 1.5s infinite;
}
@keyframes tt2-shine { 0%, 60% { left: -40%; } 100% { left: 130%; } }
.tt-guide .tt-btn:hover { color: #7F395A; transform: translateY(-2px); box-shadow: 0 0 0 1px #fff, 0 0 44px rgba(251, 109, 202, .7), 0 22px 40px -12px rgba(0, 0, 0, .7); }
.tt-guide .tt-btn-light { background: #fff; }
.tt-guide .tt-btn-tag {
  display: inline-block;
  margin-left: 12px;
  padding: 2px 10px;
  border-radius: 999px;
  background: #FF4D6A;
  color: #fff;
  font-size: 12px;
  letter-spacing: .06em;
  vertical-align: 1px;
}
.tt-guide .tt-measure-note { margin-top: 10px; padding-top: 10px; border-top: 1px dashed var(--line); font-size: 13.5px; color: #fff; }
.tt-guide .tt-measure-note strong { color: #FF8597; }

/* ---------- マーキー ---------- */
.tt-guide .tt-marquee {
  position: relative;
  z-index: 1;
  width: 112%;
  margin: calc(var(--cut) * -0.5 - 28px) 0 0 -6%;
  overflow: hidden;
  padding: 16px 0;
  transform: rotate(var(--ang));
  border-top: 1px solid rgba(251, 109, 202, .55);
  border-bottom: 1px solid rgba(251, 109, 202, .18);
  background: rgba(95, 43, 67, .82);
  box-shadow: 0 -1px 18px rgba(251, 109, 202, .35), 0 24px 40px -20px rgba(0, 0, 0, .8);
}
.tt-guide .tt-marquee-track { display: flex; width: max-content; animation: tt2-marq 38s linear infinite; }
.tt-guide .tt-marquee span {
  padding: 0 28px;
  font-family: var(--en);
  font-weight: 700;
  font-size: 34px;
  line-height: 1;
  letter-spacing: .02em;
  white-space: nowrap;
  color: transparent;
  -webkit-text-stroke: 1px rgba(253, 185, 219, .45);
}
.tt-guide .tt-marquee span:nth-child(3n+3) { color: rgba(46, 232, 154, .9); -webkit-text-stroke: 0; text-shadow: 0 0 18px rgba(46, 232, 154, .5); }
.tt-guide .tt-marquee span:nth-child(3n+4) { color: rgba(255, 77, 106, .9); -webkit-text-stroke: 0; text-shadow: 0 0 18px rgba(255, 77, 106, .5); }
.tt-guide .tt-marquee span:nth-child(3n+5) { color: rgba(167, 132, 255, .95); -webkit-text-stroke: 0; text-shadow: 0 0 18px rgba(167, 132, 255, .55); }
.tt-guide .tt-marquee span:nth-child(6n+1), .tt-guide .tt-marquee span:nth-child(6n+2), .tt-guide .tt-marquee span:nth-child(6n) { color: transparent; -webkit-text-stroke: 1px rgba(253, 185, 219, .45); text-shadow: none; }
@keyframes tt2-marq { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* ---------- まとめ ---------- */
.tt-guide .tt-summary {
  position: relative;
  margin: 56px 56px 0;
  padding: 30px 34px;
  border-radius: 24px;
  background: var(--glass);
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi), 0 30px 60px -30px rgba(0, 0, 0, .9);
  -webkit-backdrop-filter: blur(14px);
  backdrop-filter: blur(14px);
}
.tt-guide .tt-summary::before {
  content: "";
  position: absolute; left: 34px; right: 34px; top: -1px; height: 2px;
  background: linear-gradient(90deg, var(--g), var(--r), var(--v));
  border-radius: 2px;
}
.tt-guide .tt-summary-title { font-size: 17px; font-weight: 700; margin-bottom: 12px; }
.tt-guide .tt-summary dl { display: grid; grid-template-columns: 1fr 1fr; gap: 0 32px; }
.tt-guide .tt-summary dl div { display: grid; grid-template-columns: 6.5em minmax(0, 1fr); gap: 12px; padding: 11px 0; border-bottom: 1px solid var(--line); font-size: 13.5px; line-height: 1.75; }
.tt-guide .tt-summary dt { font-weight: 700; color: var(--cyan); }
.tt-guide .tt-summary dd { color: var(--tx2); }

/* ---------- 目次 ---------- */
.tt-guide .tt-toc { margin: 22px 56px 0; padding: 26px 34px; border-radius: 24px; border: 1px solid var(--line); background: rgba(255, 255, 255, .025); }
.tt-guide .tt-toc-title { font-family: var(--en); font-size: 13px; font-weight: 700; letter-spacing: .14em; color: var(--tx3); margin-bottom: 8px; }
.tt-guide .tt-toc ol { columns: 2; column-gap: 40px; counter-reset: tt2-toc; }
.tt-guide .tt-toc li { counter-increment: tt2-toc; break-inside: avoid; display: grid; grid-template-columns: 2.6em minmax(0, 1fr); align-items: baseline; padding: 4px 0; font-size: 14px; line-height: 1.6; text-wrap: balance; }
.tt-guide .tt-toc li::before { content: counter(tt2-toc, decimal-leading-zero); font-family: var(--en); font-size: 12px; color: var(--cyan); }
.tt-guide .tt-toc a { color: var(--tx); text-decoration: none; transition: color .2s; }
.tt-guide .tt-toc a:hover { color: var(--cyan); }

/* ---------- セクション共通 ---------- */
.tt-guide .tt-sec { position: relative; padding: 88px 56px 24px; scroll-margin-top: 100px; }
/* 斜めの帯（ヒーロー・医師・料金・締め の4か所だけ） */
.tt-guide .tt-sec-doctor, .tt-guide #tt-price, .tt-guide .tt-close {
  clip-path: polygon(0 var(--cut), 100% 0, 100% calc(100% - var(--cut)), 0 100%);
}
.tt-guide .tt-sec-doctor::before, .tt-guide #tt-price::before, .tt-guide .tt-close::after {
  /* 斜めの境界に沿うレーザー光のライン */
  content: "";
  position: absolute; left: 0; right: 0; top: 1px;
  height: var(--cut);
  background: linear-gradient(to top left, transparent calc(50% - 1px), var(--edge, rgba(251, 109, 202, .9)) 50%, transparent calc(50% + 1px));
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 30%, #000 70%, transparent 100%);
  mask-image: linear-gradient(90deg, transparent 0%, #000 30%, #000 70%, transparent 100%);
  filter: drop-shadow(0 0 6px var(--edge, rgba(251, 109, 202, .9)));
  pointer-events: none;
}
.tt-guide #tt-price {
  --edge: rgba(46, 232, 154, .9);
  margin-top: 40px;
  padding-top: calc(var(--cut) + 72px);
  padding-bottom: calc(var(--cut) + 24px);
  background:
    radial-gradient(700px 400px at 15% 20%, rgba(251, 109, 202, .16), transparent 65%),
    linear-gradient(180deg, #A44773 0%, #893B60 100%);
}
.tt-guide .tt-h {
  position: relative;
  margin: 0 0 34px;
  padding: 0;
  border: 0;
  background: none;
  color: #fff;
  font-family: var(--jp);
  font-weight: 700;
  font-size: 30px;
  line-height: 1.45;
  letter-spacing: .04em;
  text-wrap: balance;
}
.tt-guide .tt-h::before, .tt-guide .tt-h::after { display: none; }
.tt-guide .tt-h-en {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 10px;
  font-family: var(--en);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: .2em;
  color: var(--cyan);
}
.tt-guide .tt-h-en::before {
  content: "";
  width: 44px; height: 2px;
  background: linear-gradient(90deg, var(--cyan), transparent);
  box-shadow: 0 0 10px rgba(251, 109, 202, .8);
  transform: skewX(-30deg);
}
.tt-guide .tt-text { max-width: 41em; margin-bottom: 18px; color: var(--tx2); }
.tt-guide .tt-text:last-child { margin-bottom: 0; }
.tt-guide .tt-note { margin-top: 20px; font-size: 12.5px; line-height: 1.85; color: var(--tx3); }

/* こんな方 */
.tt-guide .tt-cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.tt-guide .tt-card {
  position: relative;
  padding: 22px 22px 22px 24px;
  border-radius: 18px;
  background: linear-gradient(160deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015));
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi);
  font-size: 14.5px;
  line-height: 1.75;
  overflow: hidden;
}
.tt-guide .tt-card::before {
  content: "";
  position: absolute; left: 0; top: 18px; bottom: 18px; width: 3px;
  border-radius: 0 3px 3px 0;
  background: linear-gradient(180deg, var(--cyan), var(--blue));
  box-shadow: 0 0 12px rgba(251, 109, 202, .8);
}
.tt-guide .tt-card p { text-wrap: wrap; }

/* ---------- 医師セクション ---------- */
.tt-guide .tt-sec-doctor {
  margin: 64px 0 0;
  padding: calc(var(--cut) + 64px) 56px calc(var(--cut) + 24px);
  background:
    radial-gradient(640px 360px at 100% 10%, rgba(250, 78, 164, .45), transparent 70%),
    radial-gradient(500px 300px at 0% 100%, rgba(167, 132, 255, .22), transparent 70%),
    linear-gradient(170deg, #16297022 0%, transparent 100%),
    linear-gradient(170deg, #A44672 0%, #A14570 100%);
}
.tt-guide .tt-decide { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin: 36px 0; counter-reset: tt2-dc; }
.tt-guide .tt-dc {
  position: relative;
  padding: 26px 24px;
  border-radius: 20px;
  background: rgba(87, 40, 62, .55);
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi), 0 24px 40px -24px rgba(0, 0, 0, .9);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  transition: transform .3s, border-color .3s;
}
.tt-guide .tt-dc:hover { transform: translateY(-4px); border-color: rgba(251, 109, 202, .5); }
.tt-guide .tt-dc-see { font-size: 13px; font-weight: 500; color: var(--tx3); text-wrap: balance; }
.tt-guide .tt-dc-arrow { position: relative; width: 100%; height: 1px; margin: 14px 0; background: linear-gradient(90deg, var(--cyan), transparent); }
.tt-guide .tt-dc-arrow::after { content: ""; position: absolute; left: 0; top: -3px; width: 7px; height: 7px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.tt-guide .tt-dc-choose { font-size: 21px; font-weight: 700; color: #fff; margin-bottom: 10px; text-wrap: balance; }
.tt-guide .tt-dc-text { font-size: 13.5px; line-height: 1.85; color: var(--tx2); }

/* ---------- 機器・モード ---------- */
/* 最終更新日 */
.tt-guide .tt-updated { margin-top: 14px; text-align: right; font-size: 12px; color: #CB9AB2; letter-spacing: .04em; }
/* 入れ墨（広い範囲）の料金例・アートメイク案内 */
.tt-guide .tt-wide { margin: 26px 0; padding: 22px 26px; border: 1px solid var(--line); border-radius: 18px; background: rgba(255, 255, 255, .04); }
.tt-guide .tt-wide-title { font-weight: 700; color: #fff; margin-bottom: 12px; }
.tt-guide .tt-wide dl { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.tt-guide .tt-wide dl div { padding: 14px 16px; border-radius: 12px; background: rgba(255, 255, 255, .06); border: 1px solid var(--line); }
.tt-guide .tt-wide dt { font-family: var(--en); font-weight: 700; font-size: 18px; color: #fff; }
.tt-guide .tt-wide dt small { display: block; font-family: inherit; font-weight: 500; font-size: 12px; color: #DAB4C7; margin-top: 2px; }
.tt-guide .tt-wide dd { margin: 6px 0 0; font-family: var(--en); font-weight: 700; font-size: 22px; color: #FB6DCA; }
.tt-guide .tt-link-box { margin-top: 18px; padding: 14px 18px; border-left: 3px solid #FF8597; border-radius: 0 12px 12px 0; background: rgba(255, 133, 151, .08); font-size: 14px; color: #EEC9DB; }
.tt-guide .tt-link-box a, .tt-guide .tt-faq a, .tt-guide .tt-text a { color: #FB6DCA; text-decoration: underline; text-underline-offset: 3px; }
/* 国内承認機 */
.tt-guide .tt-approved {
  display: flex; align-items: flex-start; gap: 22px;
  margin: 0 0 30px;
  padding: 22px 26px;
  border: 1px solid rgba(251, 109, 202, .35);
  border-radius: 18px;
  background: linear-gradient(120deg, rgba(251, 109, 202, .10), rgba(251, 109, 202, .02));
  box-shadow: 0 0 30px rgba(251, 109, 202, .10) inset;
}
.tt-guide .tt-approved-badge {
  flex: none;
  display: grid; place-items: center;
  width: 92px; height: 92px;
  border-radius: 50%;
  border: 1.5px solid #FB6DCA;
  color: #fff;
  font-size: 15px; font-weight: 700; letter-spacing: .06em;
  text-align: center;
  box-shadow: 0 0 22px rgba(251, 109, 202, .45), 0 0 0 6px rgba(251, 109, 202, .08);
}
.tt-guide .tt-approved-title { font-size: 17px; font-weight: 700; color: #fff; margin-bottom: 6px; text-wrap: balance; }
.tt-guide .tt-approved-body p:nth-child(2) { font-size: 14px; color: #ECCBDB; }
.tt-guide .tt-approved-no { margin-top: 8px; font-size: 12.5px; color: #FB6DCA; letter-spacing: .04em; }
.tt-guide .tt-split { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr); gap: 36px; align-items: start; margin-bottom: 24px; }
.tt-guide .tt-modes { display: grid; gap: 14px; }
.tt-guide .tt-mode {
  padding: 20px 22px;
  border-radius: 18px;
  background: var(--glass);
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi);
  font-size: 13px;
  line-height: 1.75;
  color: var(--tx3);
  font-family: var(--en);
}
.tt-guide .tt-mode strong { display: block; margin: 8px 0 2px; font-family: var(--jp); font-size: 17px; color: #fff; }
.tt-guide .tt-mode-tag { display: inline-block; padding: 2px 10px; border-radius: 999px; font-family: var(--en); font-size: 11px; font-weight: 700; letter-spacing: .12em; color: #622A48; background: var(--cyan); box-shadow: 0 0 14px rgba(251, 109, 202, .6); }
.tt-guide .tt-mode-tag-q { background: #fff; box-shadow: 0 0 14px rgba(255, 255, 255, .4); }

/* 皮膚断面図 */
.tt-guide .tt-skin { margin: 40px 0 34px; perspective: 1400px; }
.tt-guide .tt-skin-block {
  position: relative;
  height: 340px;
  border-radius: 22px;
  overflow: hidden;
  transform: rotateX(9deg);
  transform-origin: 50% 100%;
  box-shadow: 0 0 0 1px rgba(253, 179, 216, .22), 0 50px 70px -36px rgba(0, 0, 0, .95), 0 0 80px -10px rgba(250, 78, 164, .45);
}
.tt-guide .tt-layer { position: absolute; left: 0; right: 0; }
.tt-guide .tt-layer span { position: absolute; right: 18px; top: 10px; font-size: 12px; font-weight: 700; letter-spacing: .1em; color: rgba(255, 236, 228, .62); }
.tt-guide .tt-layer-epi { top: 0; height: 54px; background: linear-gradient(180deg, #8E6863, #74504F); box-shadow: inset 0 2px 0 rgba(255, 214, 200, .55), inset 0 -1px 0 rgba(0, 0, 0, .25); }
.tt-guide .tt-layer-der { top: 54px; height: 210px; background: linear-gradient(180deg, #5C3D45, #3F2A3A); }
.tt-guide .tt-layer-sub { top: 264px; bottom: 0; background: repeating-radial-gradient(circle at 20% 40%, #2C2440 0 14px, #3A3050 15px 16px); border-top: 1px solid rgba(0, 0, 0, .3); }
.tt-guide .tt-skin-block::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(95, 43, 67, 0) 55%, rgba(95, 43, 67, .55));
  pointer-events: none;
}
.tt-guide .tt-ink { position: absolute; z-index: 2; border-radius: 50%; box-shadow: 0 0 0 2px rgba(255, 255, 255, .7), 0 0 14px rgba(255, 255, 255, .35); }
.tt-guide .tt-ink-a { left: calc(18% - 2px); top: 38px; width: 16px; height: 16px; background: #E23A44; }
.tt-guide .tt-ink-b { left: calc(18% + 12px); top: 52px; width: 12px; height: 12px; background: #F08A2E; }
.tt-guide .tt-ink-c { left: calc(49% - 2px); top: 102px; width: 18px; height: 18px; background: #2E62C9; }
.tt-guide .tt-ink-d { left: calc(49% + 14px); top: 116px; width: 13px; height: 13px; background: #279158; }
.tt-guide .tt-ink-e { left: calc(80% - 2px); top: 160px; width: 22px; height: 22px; background: #15161A; }
.tt-guide .tt-ink-f { left: calc(80% + 16px); top: 178px; width: 15px; height: 15px; background: #1F2A55; }
.tt-guide .tt-ray {
  position: absolute; top: 0; z-index: 1;
  width: 26px;
  border-radius: 0 0 13px 13px;
  transform-origin: top;
  animation: tt2-ray 1.4s cubic-bezier(.2, .8, .2, 1) both;
}
.tt-guide .tt-ray b {
  position: absolute; left: calc(100% + 26px); bottom: -10px;
  padding: 3px 11px;
  border-radius: 999px;
  background: #7F395A;
  font-family: var(--en); font-weight: 700; font-size: 13px;
  white-space: nowrap;
  box-shadow: 0 0 0 1px currentColor, 0 6px 16px rgba(0, 0, 0, .4);
}
.tt-guide .tt-ray-532 { left: calc(18% - 6px); height: 104px; background: linear-gradient(180deg, rgba(46, 232, 154, .15), rgba(46, 232, 154, .95)); box-shadow: 0 0 26px rgba(46, 232, 154, .85); }
.tt-guide .tt-ray-532 b { color: var(--g); }
.tt-guide .tt-ray-694 { left: calc(49% - 4px); height: 168px; background: linear-gradient(180deg, rgba(255, 77, 106, .15), rgba(255, 77, 106, .95)); box-shadow: 0 0 26px rgba(255, 77, 106, .8); animation-delay: .15s; }
.tt-guide .tt-ray-694 b { color: #FF7A90; }
.tt-guide .tt-ray-1064 { left: calc(80% - 2px); height: 226px; background: linear-gradient(180deg, rgba(167, 132, 255, .15), rgba(167, 132, 255, .95)); box-shadow: 0 0 26px rgba(167, 132, 255, .85); animation-delay: .3s; }
.tt-guide .tt-ray-1064 b { color: var(--v); }
@keyframes tt2-ray { from { transform: scaleY(0); opacity: 0; } to { transform: scaleY(1); opacity: 1; } }
.tt-guide .tt-skin figcaption { margin-top: 18px; text-align: center; font-size: 12.5px; color: var(--tx3); text-wrap: balance; }

/* 波長カード */
.tt-guide .tt-waves { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
.tt-guide .tt-wave {
  --c: var(--cyan);
  position: relative;
  padding: 28px 24px 24px;
  border-radius: 22px;
  background: linear-gradient(170deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015));
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi), 0 30px 50px -30px rgba(0, 0, 0, .9);
  overflow: hidden;
  transition: transform .35s, box-shadow .35s;
}
.tt-guide .tt-wave::before {
  content: "";
  position: absolute; left: -20%; right: -20%; top: -60px; height: 120px;
  background: radial-gradient(closest-side, var(--c), transparent);
  opacity: .28;
}
.tt-guide .tt-wave:hover { transform: translateY(-6px); box-shadow: inset 0 1px 0 var(--hi), 0 0 0 1px var(--c), 0 30px 60px -24px var(--c); }
.tt-guide .tt-wave-532 { --c: var(--g); }
.tt-guide .tt-wave-694 { --c: var(--r); }
.tt-guide .tt-wave-1064 { --c: var(--v); }
.tt-guide .tt-wave-nm { position: relative; font-family: var(--en); font-weight: 700; font-size: 54px; line-height: 1; letter-spacing: -.02em; color: var(--c); text-shadow: 0 0 24px var(--c); }
.tt-guide .tt-wave-nm span { font-size: 18px; margin-left: 4px; letter-spacing: 0; }
.tt-guide .tt-wave-name { position: relative; margin-top: 14px; font-size: 12.5px; color: var(--tx3); }
.tt-guide .tt-wave-target { position: relative; margin-top: 6px; font-size: 14px; line-height: 1.75; letter-spacing: .02em; text-wrap: balance; }
.tt-guide .tt-chips { display: flex; gap: 7px; margin-top: 16px; }
.tt-guide .tt-chip { width: 16px; height: 16px; border-radius: 50%; box-shadow: 0 0 0 2px var(--bg1), 0 0 0 3px rgba(255, 255, 255, .3); }
.tt-guide .tt-c-red { background: #E23A44; }
.tt-guide .tt-c-orange { background: #F08A2E; }
.tt-guide .tt-c-yellow { background: #F2CB3A; }
.tt-guide .tt-c-brown { background: #8A5A3B; }
.tt-guide .tt-c-purple { background: #8B47C9; }
.tt-guide .tt-c-blue { background: #2E62C9; }
.tt-guide .tt-c-green { background: #279158; }
.tt-guide .tt-c-black { background: #000; box-shadow: 0 0 0 2px var(--bg1), 0 0 0 3px rgba(255, 255, 255, .55); }
.tt-guide .tt-c-navy { background: #1F2A55; box-shadow: 0 0 0 2px var(--bg1), 0 0 0 3px rgba(255, 255, 255, .55); }
.tt-guide .tt-c-darkbrown { background: #4A2E22; box-shadow: 0 0 0 2px var(--bg1), 0 0 0 3px rgba(255, 255, 255, .55); }

/* ---------- アートメイク ---------- */
.tt-guide #tt-artmake { padding-left: 56px; }
.tt-guide #tt-artmake .tt-text { padding-left: 22px; border-left: 1px solid rgba(167, 132, 255, .5); }

/* ---------- 症例（明るいカード） ---------- */
.tt-guide .tt-cases { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; margin-bottom: 22px; }
.tt-guide .tt-case {
  padding: 12px 12px 14px;
  border-radius: 22px;
  background: #FDB9DA;
  color: #7F395A;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .7), 0 0 50px -16px rgba(251, 109, 202, .55), 0 36px 60px -30px rgba(0, 0, 0, .95);
  transition: transform .35s;
}
.tt-guide .tt-case:hover { transform: translateY(-6px) rotate(-.4deg); }
.tt-guide .tt-ba { display: grid; grid-template-columns: 1fr 1fr; gap: 3px; border-radius: 14px; overflow: hidden; }
.tt-guide .tt-ba figure { position: relative; }
.tt-guide .tt-ba img { width: 100%; aspect-ratio: 1; object-fit: cover; }
.tt-guide .tt-ba figcaption {
  position: absolute; left: 8px; bottom: 8px;
  padding: 1px 9px;
  border-radius: 999px;
  background: rgba(87, 40, 62, .82);
  color: #fff;
  font-size: 11px; font-weight: 700;
  white-space: nowrap;
}
.tt-guide .tt-ba figure + figure figcaption { background: var(--blue); }
.tt-guide .tt-case-cap { margin-top: 10px; padding: 0 4px; font-size: 12px; line-height: 1.6; color: #7D4861; text-wrap: balance; }
.tt-guide .tt-case-detail {
  padding: 18px 26px;
  border-radius: 20px;
  background: var(--glass);
  border: 1px solid var(--line);
  font-size: 13.5px;
}
.tt-guide .tt-case-detail div { display: grid; grid-template-columns: 8.5em minmax(0, 1fr); gap: 14px; padding: 9px 0; border-bottom: 1px solid var(--line); }
.tt-guide .tt-case-detail div:last-child { border-bottom: 0; }
.tt-guide .tt-case-detail dt { font-weight: 700; color: #fff; }
.tt-guide .tt-case-detail dd { color: var(--tx2); }

/* ---------- 回数・間隔 ---------- */
.tt-guide .tt-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 26px; }
.tt-guide .tt-fact {
  position: relative;
  padding: 30px 30px 28px;
  border-radius: 22px;
  background: var(--glass);
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi), 0 30px 50px -30px rgba(0, 0, 0, .9);
  overflow: hidden;
}
.tt-guide .tt-fact::after {
  content: "";
  position: absolute; right: -30px; bottom: -40px;
  width: 160px; height: 160px; border-radius: 50%;
  background: radial-gradient(closest-side, rgba(251, 109, 202, .22), transparent);
}
.tt-guide .tt-fact-label { font-size: 13px; color: var(--tx3); }
.tt-guide .tt-fact-value { margin: 6px 0 10px; font-family: var(--en); font-weight: 700; font-size: 52px; line-height: 1.1; color: #fff; letter-spacing: -.01em; }
.tt-guide .tt-fact-value small { margin-left: 8px; font-family: var(--jp); font-size: 16px; font-weight: 500; color: var(--cyan); letter-spacing: .04em; }
.tt-guide .tt-fact-text { font-size: 13.5px; line-height: 1.85; color: var(--tx2); }

/* ---------- 料金（明るいカード） ---------- */
/* 面積の測り方（タトゥーを囲む長方形の長辺×短辺） */
.tt-guide .tt-measure {
  display: flex; align-items: center; gap: 28px;
  margin: 26px 0 0;
  padding: 22px 26px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255, 255, 255, .04);
}
.tt-guide .tt-measure-img { flex: none; width: 280px; max-width: 100%; height: auto; }
.tt-guide .tt-measure-title { font-weight: 700; color: #fff; margin-bottom: 4px; }
.tt-guide .tt-measure-text p:nth-child(2) { font-size: 14px; color: #ECCBDB; }
.tt-guide .tt-measure-text strong { color: #FB6DCA; }
.tt-guide .tt-price-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin: 30px 0 18px; }
.tt-guide .tt-plan {
  position: relative;
  padding: 26px 16px 24px;
  border-radius: 22px;
  background: linear-gradient(180deg, #FFFFFF, #FDB9DB);
  color: #7F395A;
  text-align: center;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .8), 0 0 40px -14px rgba(251, 109, 202, .6), 0 30px 50px -26px rgba(0, 0, 0, .95);
  transition: transform .3s, box-shadow .3s;
}
.tt-guide .tt-plan:hover { transform: translateY(-6px); box-shadow: 0 0 0 1px #fff, 0 0 60px -10px rgba(251, 109, 202, .85), 0 36px 60px -26px rgba(0, 0, 0, .95); }
.tt-guide .tt-plan-area { font-family: var(--en); font-weight: 700; font-size: 24px; letter-spacing: -.01em; }
.tt-guide .tt-plan-area span { font-size: 14px; margin-left: 2px; }
.tt-guide .tt-plan-size { min-height: 1.6em; font-size: 13px; color: #925973; }
.tt-guide .tt-plan-yen { margin-top: 14px; padding-top: 14px; border-top: 1px solid #EEC9DB; font-family: var(--en); font-weight: 700; font-size: 31px; line-height: 1.2; color: #DA2075; letter-spacing: -.01em; white-space: nowrap; }
.tt-guide .tt-plan-yen span { margin-left: 2px; font-family: var(--jp); font-size: 14px; }
.tt-guide .tt-over {
  padding: 26px 30px;
  border-radius: 22px;
  background: var(--glass);
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi);
}
.tt-guide .tt-over-head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 16px; margin-bottom: 14px; }
.tt-guide .tt-over-label { padding: 4px 14px; border-radius: 999px; background: #fff; color: #7F395A; font-size: 13px; font-weight: 700; }
.tt-guide .tt-over-rule { font-size: 15px; color: var(--tx2); }
.tt-guide .tt-over-rule strong { margin-left: 6px; font-family: var(--en); font-size: 24px; color: var(--cyan); }
.tt-guide .tt-over dl { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.tt-guide .tt-over dl div { padding: 14px 18px; border-radius: 14px; background: rgba(255, 255, 255, .05); border: 1px solid var(--line); }
.tt-guide .tt-over dt { font-family: var(--en); font-size: 15px; font-weight: 500; }
.tt-guide .tt-over dt small { margin-left: 6px; font-family: var(--jp); font-size: 11px; color: var(--tx3); }
.tt-guide .tt-over dd { font-family: var(--en); font-weight: 700; font-size: 24px; color: #fff; white-space: nowrap; }
.tt-guide .tt-notes { margin-top: 20px; font-size: 13.5px; color: var(--tx2); }
.tt-guide .tt-notes li { position: relative; padding-left: 1.3em; margin-bottom: 4px; text-wrap: wrap; }
.tt-guide .tt-notes li::before { content: "※"; position: absolute; left: 0; color: var(--tx3); }

/* ---------- 流れ ---------- */
.tt-guide .tt-steps { position: relative; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; counter-reset: tt2-step; }
.tt-guide .tt-steps li {
  position: relative;
  counter-increment: tt2-step;
  padding: 24px 22px 22px;
  border-radius: 20px;
  background: linear-gradient(170deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015));
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi);
}
.tt-guide .tt-steps li::before {
  content: counter(tt2-step, decimal-leading-zero);
  display: block;
  margin-bottom: 8px;
  font-family: var(--en);
  font-weight: 700;
  font-size: 34px;
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px var(--cyan);
}
.tt-guide .tt-step-title { font-size: 17px; font-weight: 700; text-wrap: balance; }
.tt-guide .tt-step-text { margin-top: 6px; font-size: 13.5px; line-height: 1.85; color: var(--tx2); }

/* ---------- 経過 ---------- */
.tt-guide .tt-timeline { position: relative; display: grid; gap: 14px; padding-left: 30px; }
.tt-guide .tt-timeline::before { content: ""; position: absolute; left: 7px; top: 12px; bottom: 12px; width: 2px; border-radius: 2px; background: linear-gradient(180deg, var(--r), var(--v), var(--cyan)); box-shadow: 0 0 12px rgba(167, 132, 255, .6); }
.tt-guide .tt-tl {
  position: relative;
  display: grid;
  grid-template-columns: 9.5em minmax(0, 1fr) minmax(0, 1fr);
  gap: 20px;
  padding: 20px 24px;
  border-radius: 18px;
  background: var(--glass);
  border: 1px solid var(--line);
  font-size: 13.5px;
  line-height: 1.85;
  color: var(--tx2);
}
.tt-guide .tt-tl::before { content: ""; position: absolute; left: -29px; top: 26px; width: 14px; height: 14px; border-radius: 50%; background: var(--bg0); border: 2px solid var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.tt-guide .tt-tl-when { font-size: 15px; font-weight: 700; color: #fff; text-wrap: balance; }
.tt-guide .tt-tl-state, .tt-guide .tt-tl-care { text-wrap: wrap; }
.tt-guide .tt-tl-care { color: #FDB2E2; }
.tt-guide .tt-tl-state { color: var(--tx); }

/* ---------- リスク ---------- */
.tt-guide .tt-risks { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.tt-guide .tt-risks li {
  position: relative;
  padding: 20px 20px 20px 22px;
  border-radius: 16px;
  background: linear-gradient(170deg, rgba(255, 255, 255, .075), rgba(255, 255, 255, .02));
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--hi);
  font-size: 13.5px; line-height: 1.85; color: var(--tx2);
}
.tt-guide .tt-risks li::before { content: ""; position: absolute; left: 0; top: 22px; width: 3px; height: 18px; border-radius: 0 3px 3px 0; background: var(--r); box-shadow: 0 0 10px var(--r); }
.tt-guide .tt-risks strong { display: block; margin-bottom: 6px; font-size: 15.5px; color: #fff; text-wrap: balance; }

/* ---------- 受けられない方 ---------- */
.tt-guide .tt-checks { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 12px; margin-top: 8px; }
.tt-guide .tt-checks li { position: relative; padding: 14px 18px 14px 44px; border-radius: 14px; background: rgba(255, 77, 106, .06); border: 1px solid rgba(255, 77, 106, .22); color: var(--tx); font-size: 14.5px; line-height: 1.7; }
.tt-guide .tt-checks li::before { content: ""; position: absolute; left: 18px; top: 50%; width: 12px; height: 2px; background: var(--r); box-shadow: 0 0 8px var(--r); transform: translateY(-50%) rotate(45deg); }
.tt-guide .tt-checks li::after { content: ""; position: absolute; left: 18px; top: 50%; width: 12px; height: 2px; background: var(--r); transform: translateY(-50%) rotate(-45deg); }

/* ---------- FAQ ---------- */
.tt-guide .tt-faq { display: grid; gap: 12px; }
.tt-guide .tt-faq dt {
  position: relative;
  padding: 20px 26px 6px 66px;
  border-radius: 18px 18px 0 0;
  background: rgba(158, 77, 115, .55);
  border: 1px solid var(--line);
  border-bottom: 0;
  font-size: 15.5px;
  font-weight: 700;
  color: #fff;
  text-wrap: balance;
}
.tt-guide .tt-faq dd {
  position: relative;
  margin-top: -12px;
  padding: 8px 26px 20px 66px;
  border-radius: 0 0 18px 18px;
  background: rgba(158, 77, 115, .55);
  border: 1px solid var(--line);
  border-top: 0;
  font-size: 14px;
  line-height: 1.9;
  color: var(--tx2);
}
.tt-guide .tt-faq dt::before, .tt-guide .tt-faq dd::before {
  position: absolute; left: 22px;
  display: grid; place-items: center;
  width: 28px; height: 28px;
  border-radius: 50%;
  font-family: var(--en); font-size: 13px; font-weight: 700;
}
.tt-guide .tt-faq dt::before { content: "Q"; top: 19px; background: var(--cyan); color: #622A48; box-shadow: 0 0 14px rgba(251, 109, 202, .6); }
.tt-guide .tt-faq dd::before { content: "A"; top: 6px; border: 1px solid var(--line); color: var(--tx); }

/* ---------- 締め ---------- */
.tt-guide .tt-close {
  position: relative;
  --edge: rgba(167, 132, 255, .95);
  margin: 72px 0 0;
  padding: calc(var(--cut) + 72px) 32px calc(var(--cut) + 40px);
