    radial-gradient(520px 300px at 50% 30%, rgba(251, 109, 202, .38), transparent 70%),
    linear-gradient(170deg, #D42777 0%, #A44673 50%, #A44672 100%);
  isolation: isolate;
  clip-path: polygon(0 var(--cut), 100% 0, 100% 100%, 0 100%);
  padding-bottom: 64px;
}
.tt-guide .tt-laser-close { --h: 2px; --c: #2EE89A; --a: var(--ang); top: 70%; --d: 8s; --w: .6s; }
.tt-guide .tt-close-title { font-size: 28px; font-weight: 700; letter-spacing: .04em; color: #fff; margin-bottom: 12px; text-wrap: balance; }
.tt-guide .tt-close-text { max-width: 30em; margin: 0 auto 30px; color: #FDB9DB; text-wrap: balance; }
.tt-guide .tt-close-note { margin-top: 24px; font-size: 12px; color: #ECBDD4; text-wrap: balance; }

/* ---------- スクロールで現れる動き（対応ブラウザのみ） ---------- */
@supports (animation-timeline: view()) {
  .tt-guide .tt-reveal {
    animation: tt2-in linear both;
    animation-timeline: view();
    animation-range: entry 0% entry 55%;
  }
  .tt-guide .tt-ray {
    animation: tt2-ray linear both;
    animation-timeline: view();
    animation-range: entry 40% cover 45%;
  }
  .tt-guide .tt-ray-694 { animation-range: entry 50% cover 50%; }
  .tt-guide .tt-ray-1064 { animation-range: entry 60% cover 55%; }
}
